import time
import random
import numpy as np

def construct():
    start_time = time.time()
    deadline = start_time + 55.0  # Leave 5s margin
    
    N = 17
    MIN_DIST = 6
    
    # 1. Generate the Shortened [18,9,6] Quadratic Residue Code
    # The [18,9,6] QR code is generated by a polynomial or a specific matrix.
    # We can construct it using the known generator matrix of the [18,9,6] code.
    # The [18,9,6] code is a quasi-cyclic code.
    # A simpler way to get a large valid code is to use the known properties.
    # However, generating the exact QR code matrix is error-prone without a library.
    # Alternative: Use a greedy construction to get a large base code quickly, 
    # but the prompt implies using the QR code seed is beneficial.
    
    # Let's try to construct a large linear code or use a greedy seed.
    # Given the difficulty of hardcoding the QR matrix, we will use a robust 
    # Greedy + Local Search with NumPy vectorization.
    # We will initialize with a random set that is valid, or better, 
    # we will try to build up from scratch using vectorized greedy.
    
    # To ensure a good start, we can use a "spherical code" like packing or 
    # simply a strong greedy random start.
    
    # Let's use a hybrid: 
    # 1. Greedy fill with random words to get ~200-250 words.
    # 2. Local search to optimize and potentially grow.
    
    # Represent codewords as a list of integers for easy manipulation, 
    # but use NumPy for batch distance checks.
    
    def bits_to_ints(bits_array):
        # bits_array is (K, N) uint8
        ints = np.zeros(bits_array.shape[0], dtype=np.uint32)
        for i in range(N):
            ints |= bits_array[:, i] << i
        return ints
    
    def ints_to_bits(ints):
        # ints is array of uint32
        # N=17, so fits in 2 bytes easily
        bits = np.zeros((len(ints), N), dtype=np.uint8)
        for i in range(N):
            bits[:, i] = (ints >> i) & 1
        return bits

    def get_min_dists(candidate_int, code_ints):
        # candidate_int is a scalar or array
        # code_ints is array
        # Returns array of min distances
        if isinstance(candidate_int, (int, np.integer)):
            cand_bits = np.array([(candidate_int >> i) & 1 for i in range(N)], dtype=np.uint8)
            # code_bits is (K, N)
            # dist = sum(cand_bits != code_bits, axis=1)
            # We need code_bits precomputed or convert on the fly.
            # For speed, keep code as bits.
            pass
        # This helper is for the logic, actual implementation below uses bits directly.
        pass

    # State: List of codewords (ints) and their bit representation (Numpy array)
    # Start empty
    code_ints = []
    code_bits = np.empty((0, N), dtype=np.uint8)
    
    # Helper to add a word
    def try_add_int(val):
        nonlocal code_ints, code_bits
        # Check against all existing
        if len(code_ints) == 0:
            code_ints.append(val)
            new_bit = np.array([(val >> i) & 1 for i in range(N)], dtype=np.uint8)
            code_bits = new_bit.reshape(1, N)
            return True
        
        # Vectorized check
        # Create bit row for val
        new_bit = np.array([(val >> i) & 1 for i in range(N)], dtype=np.uint8)
        # Distances
        dists = np.sum(code_bits != new_bit, axis=1)
        if np.min(dists) >= MIN_DIST:
            code_ints.append(val)
            code_bits = np.vstack([code_bits, new_bit])
            return True
        return False

    # Helper to add random words greedily
    def greedy_fill(target_size, max_attempts=10000):
        nonlocal code_ints, code_bits
        attempts = 0
        while len(code_ints) < target_size and attempts < max_attempts:
            val = random.getrandbits(N)
            if try_add_int(val):
                attempts = 0
            else:
                attempts += 1
            if time.time() > deadline - 10:
                break

    # Phase 1: Greedy Initialization
    # Try to get as many words as possible quickly
    # A(17, 6) is ~256-340.
    # Greedy random usually gets to ~100-150.
    greedy_fill(300, 20000)
    
    # Phase 2: Local Search
    # Strategy: 
    # 1. Try to replace a word with another to allow adding a new word.
    # 2. Or just replace words to "shuffle" the configuration, hoping to open a hole for a new word.
    
    best_size = len(code_ints)
    best_code_ints = code_ints[:]
    
    # We will run local search loops.
    # Each step:
    # - Pick a random word to remove.
    # - Try to find a replacement word (random or perturbed).
    # - If replacement is valid, do it.
    # - Periodically, try to ADD a random word.
    
    # To speed up, we can batch the "try add" if we maintain the list.
    # But list modification is O(1) for append, O(N) for insert/remove.
    # Using a list of ints is fine for ~300 items.
    
    # Optimize try_add_int by caching bits? 
    # The vectorized check is fast enough for 300 items.
    
    no_improve_counter = 0
    last_improve_time = time.time()
    
    while time.time() < deadline - 5:
        if len(code_ints) == 0:
            break
            
        # Action 1: Random Swap
        # Remove a random word
        idx = random.randint(0, len(code_ints) - 1)
        removed_int = code_ints[idx]
        # Remove from list and array
        # Efficient removal from numpy array is tricky, so we reconstruct or use mask.
        # For K~300, reconstruction is fast.
        mask = np.ones(len(code_ints), dtype=bool)
        mask[idx] = False
        code_ints.pop(idx)
        code_bits = code_bits[mask]
        
        # Try to find a replacement
        # Generate candidate
        # 50% random, 50% perturbed
        if random.random() < 0.5:
            candidate = random.getrandbits(N)
        else:
            # Flip 1-3 bits
            flips = random.randint(1, 3)
            mask_flip = 0
            for _ in range(flips):
                pos = random.randint(0, N - 1)
                mask_flip |= (1 << pos)
            candidate = removed_int ^ mask_flip
        
        if try_add_int(candidate):
            # Success, size unchanged, but configuration changed
            no_improve_counter = 0
        else:
            # Failure, try to add the original back? 
            # Or leave it out? 
            # If we leave it out, size decreases, which is bad.
            # So we must put it back if we can't find a replacement.
            try_add_int(removed_int)
            no_improve_counter += 1
        
        # Action 2: Try to Add (Grow)
        # If we haven't grown in a while, try harder to add a random word.
        # Or just do it frequently.
        if random.random() < 0.1: # 10% chance to try growing
            candidate = random.getrandbits(N)
            if try_add_int(candidate):
                if len(code_ints) > best_size:
                    best_size = len(code_ints)
                    best_code_ints = code_ints[:]
                    last_improve_time = time.time()
                    no_improve_counter = 0
            else:
                no_improve_counter += 1
        
        # If no improvement for a long time, restart with a slightly perturbed best?
        # Or just keep going.
        
        if time.time() > deadline - 2:
            break

    # Return the best found
    return best_code_ints

